 static void definitions(Connection c,String table,Map<String,String> expected)throws SQLException{
  String timezone,dateStyle;try(var q=c.createStatement();var r=q.executeQuery("SELECT current_setting('TimeZone'),current_setting('DateStyle')")){if(!r.next())throw new IllegalStateException("Missing catalog session");timezone=r.getString(1);dateStyle=r.getString(2);}
  try{var actual=new TreeMap<String,String>();try(var q=c.prepareStatement("SELECT conname,CASE WHEN set_config('TimeZone','UTC',true)='UTC' AND set_config('DateStyle','ISO, MDY',true)='ISO, MDY' THEN encode(sha256(convert_to(pg_get_constraintdef(oid),'UTF8')),'hex') END FROM pg_constraint WHERE conrelid=to_regclass(?) ORDER BY conname")){q.setString(1,"public."+table);try(var r=q.executeQuery()){while(r.next())actual.put(r.getString(1),r.getString(2));}}requireDefinitions(expected,actual);
  }finally{try(var q=c.prepareStatement("SELECT set_config('TimeZone',?,true),set_config('DateStyle',?,true)")){q.setString(1,timezone);q.setString(2,dateStyle);q.execute();}}
 }
